#include <iostream>
#include <memory>
#include <string>

class Resource {
public:
    explicit Resource(std::string name) : name_(std::move(name)) { std::cout << "open " << name_ << "\n"; }
    ~Resource() { std::cout << "close " << name_ << "\n"; }
private:
    std::string name_;
};

int main() {
    Resource a("A");
    {
        Resource b("B");
        auto c = std::make_unique<Resource>("C");
    }                                    // c, then b, are destroyed here
    std::cout << "end of main\n";
}                                        // a is destroyed here
